<template><section class="credit-panel"><p class="credit-notice">Credit nội bộ dùng cho cạnh tranh banner. Không phải tiền thật, không thanh toán đơn hàng và không nạp/rút.</p><p v-if="loading" role="status">Đang tải ví…</p><div v-if="error" class="management-error" role="alert">{{ error }} <button class="button button-outline" @click="load()">Thử tải lại</button></div><p v-if="success" role="status">{{ success }}</p>
  <template v-if="balance"><dl class="statistics-summary"><div><dt>Credit khả dụng</dt><dd>{{ points(balance.available) }}</dd></div><div><dt>Credit đang giữ cho banner</dt><dd>{{ points(balance.reserved) }}</dd></div></dl></template>
  <form class="credit-filters" @submit.prevent="load(0)"><label class="management-field">Loại giao dịch<select v-model="type"><option value="">Tất cả</option><option v-for="(label,key) in kinds" :key="key" :value="key">{{ label }}</option></select></label><label class="management-field">Trạng thái<select v-model="status"><option value="">Tất cả</option><option value="COMPLETED">Đã ghi sổ</option><option value="PENDING">Đang xử lý</option><option value="FAILED">Thất bại</option></select></label><button class="button button-outline" :disabled="loading">Lọc</button></form>
  <p>Giao dịch chỉ xuất hiện sau khi ghi sổ nguyên tử. Khoản giữ chỗ đã được ghi sổ được hiển thị ở số credit đang giữ; yêu cầu bị từ chối không tạo giao dịch thành công.</p>
  <div v-if="history" class="credit-history"><article v-for="row in history.content" :key="row.id" class="market-panel"><h3>{{ kinds[row.type] }}</h3><p>{{ row.description }}</p><p>Khả dụng: {{ signed(row.availableDelta) }} · Đang giữ: {{ signed(row.reservedDelta) }}</p><p>Đã ghi sổ · <time :datetime="row.createdAt">{{ new Date(row.createdAt).toLocaleString('vi-VN') }}</time></p><button class="button button-outline" @click="detail(row.id)">Xem chi tiết</button></article><p v-if="!history.content.length">Không có giao dịch khớp bộ lọc.</p><nav aria-label="Phân trang giao dịch"><button class="button button-outline" :disabled="loading||history.page===0" @click="load(history.page-1)">Trang trước</button><span>Trang {{ history.page+1 }}</span><button class="button button-outline" :disabled="loading||history.page+1>=history.totalPages" @click="load(history.page+1)">Trang sau</button></nav></div>
  <dialog ref="dialog" aria-labelledby="credit-detail-title"><h2 id="credit-detail-title">Chi tiết giao dịch credit</h2><template v-if="selected"><p>{{ kinds[selected.type] }} · Đã ghi sổ</p><p>{{ selected.description }}</p><p>Mã tham chiếu: {{ selected.reference }}</p><p>Khả dụng: {{ signed(selected.availableDelta) }} · Đang giữ: {{ signed(selected.reservedDelta) }}</p></template><button class="button button-outline" @click="dialog.close()">Đóng</button></dialog>
  <section v-if="admin" class="market-panel"><h2>Cấp credit nội bộ có kiểm soát</h2><p>Chỉ Admin được cấp. Mọi lần cấp có bút toán nguồn đối ứng và lý do; không xác nhận nạp tiền thật.</p><div class="management-toolbar"><label class="management-field">Tìm tài khoản nhận<input v-model="userSearch" type="search" maxlength="160" :disabled="busy||!!pending||usersLoading" @keyup.enter.prevent="loadUsers(0)"/></label><button type="button" class="button button-outline" :disabled="busy||!!pending||usersLoading" @click="loadUsers(0)">Tìm tài khoản</button></div><p v-if="usersLoading" role="status">Đang tìm tài khoản…</p><p v-else-if="!users.length">Không có tài khoản khớp từ khóa.</p><nav aria-label="Phân trang tài khoản nhận"><button type="button" class="button button-outline" :disabled="busy||!!pending||usersLoading||userPage===0" @click="loadUsers(userPage-1)">Tài khoản trước</button><span>Trang {{ userPage+1 }}</span><button type="button" class="button button-outline" :disabled="busy||!!pending||usersLoading||userPage+1>=userPages" @click="loadUsers(userPage+1)">Tài khoản sau</button></nav><form class="management-form" @submit.prevent="grant"><label class="management-field">Tài khoản nhận<select v-model="grantForm.ownerId" required :disabled="busy||!!pending"><option value="">Chọn tài khoản</option><option v-for="u in users" :key="u.id" :value="u.id">{{ u.name }} · {{ u.email }}</option></select></label><label class="management-field">Số credit<input v-model="grantForm.credits" type="number" min="1" max="1000000" step="1" required :disabled="busy||!!pending"/></label><label class="management-field">Lý do<textarea v-model="grantForm.reason" minlength="8" maxlength="1000" required :disabled="busy||!!pending"/></label><button class="button button-primary" :disabled="busy">{{ busy?'Đang xử lý…':pending?'Thử lại đúng yêu cầu đang chờ':'Cấp credit nội bộ' }}</button><button v-if="pending&&knownRejected" type="button" class="button button-outline" @click="discard">Bỏ yêu cầu đã bị từ chối</button></form><p v-if="pending" role="status">Đang giữ nguyên mã và dữ liệu yêu cầu. Không tạo giao dịch mới khi kết quả chưa rõ.</p><button class="button button-outline" @click="reconcile">Đối chiếu sổ và số dư</button><p v-if="reconciliation!==null" role="status">{{ reconciliation.length?'Có chênh lệch cần điều tra: '+reconciliation.length:'Không phát hiện chênh lệch số dư với sổ giao dịch.' }}</p></section>
</section></template>
<script setup>
import {ref,onMounted} from 'vue';import {marketplaceRequest as request} from '../../services/marketplace.js';import {useAuth} from '../../composables/useAuth.js';
const props=defineProps({admin:Boolean}),{user}=useAuth(),balance=ref(null),history=ref(null),loading=ref(false),error=ref(''),success=ref(''),type=ref(''),status=ref(''),selected=ref(null),dialog=ref(null),users=ref([]),busy=ref(false),pending=ref(null),knownRejected=ref(false),grantForm=ref({ownerId:'',credits:'',reason:''}),reconciliation=ref(null);
const userSearch=ref(''),userPage=ref(0),userPages=ref(0),usersLoading=ref(false);
async function loadUsers(page=0){if(pending.value)return;usersLoading.value=true;error.value='';try{const result=await request('/admin/users?'+new URLSearchParams({search:userSearch.value,page}));users.value=result.content;userPage.value=result.page;userPages.value=result.totalPages;grantForm.value.ownerId='';}catch(e){error.value=e.message;}finally{usersLoading.value=false;}}
const kinds={GRANT:'Cấp credit nội bộ',RESERVE:'Giữ credit cho banner',RELEASE:'Giải phóng credit',CHARGE:'Sử dụng credit cho banner'},points=v=>new Intl.NumberFormat('vi-VN').format(BigInt(String(v))),signed=v=>(Number(v)>0?'+':'')+points(v),storageKey=()=> 'bm:credit-grant:'+user.value?.id;
async function load(page=history.value?.page||0){loading.value=true;error.value='';try{const [b,h]=await Promise.all([request('/account/wallet'),request('/account/wallet/transactions?'+new URLSearchParams({page,type:type.value,status:status.value}))]);balance.value=b;history.value=h;}catch(e){error.value=e.message;}finally{loading.value=false;}}
async function detail(id){try{selected.value=await request('/account/wallet/transactions/'+id);dialog.value.showModal();}catch(e){error.value=e.message;}}
async function grant(){if(busy.value)return;busy.value=true;error.value='';knownRejected.value=false;try{if(!pending.value){pending.value={ownerId:Number(grantForm.value.ownerId),credits:Number(grantForm.value.credits),reason:grantForm.value.reason,requestKey:crypto.randomUUID()};sessionStorage.setItem(storageKey(),JSON.stringify(pending.value));}await request('/admin/wallet/grants','POST',pending.value);discard();success.value='Đã ghi sổ cấp credit nội bộ.';await load();}catch(e){error.value=e.message;knownRejected.value=[400,403,409].includes(e.status);}finally{busy.value=false;}}
function discard(){pending.value=null;knownRejected.value=false;sessionStorage.removeItem(storageKey());}
async function reconcile(){try{reconciliation.value=await request('/admin/wallet/reconciliation');}catch(e){error.value=e.message;}}
onMounted(async()=>{await load();if(props.admin){try{await loadUsers();const old=sessionStorage.getItem(storageKey());if(old){pending.value=JSON.parse(old);grantForm.value={...pending.value};}}catch(e){error.value=e.message;}}});
</script>
<style scoped>.credit-notice{padding:var(--bm-space-4);background:var(--bm-soft);border-radius:var(--bm-radius);line-height:1.7}.credit-filters{display:flex;align-items:end;gap:var(--bm-space-4);flex-wrap:wrap;margin-block:var(--bm-space-5)}.credit-filters label{display:grid;gap:8px}.credit-filters select{min-height:44px;padding:8px}.credit-history{display:grid;gap:var(--bm-space-4)}.credit-history nav{display:flex;align-items:center;gap:20px}.credit-panel>section{margin-top:32px}.credit-panel dialog{max-width:640px;padding:32px;border:1px solid var(--bm-border);border-radius:var(--bm-radius);color:var(--bm-ink)}.credit-panel dialog::backdrop{background:rgb(0 0 0 / .4)}</style>
